import React, { useState } from 'react';
import { FaFilter, FaPlus } from 'react-icons/fa';
import Button from '../../components/common/Button/Button';
import AdvertCard from '../../components/AdvertCard/AdvertCard';
import FilterSection from '../../components/FilterSection/FilterSection';
import Modal from '../../components/common/Modal/Modal';
import styles from './HomePage.module.css';

const HomePage = () => {
    const [activeTab, setActiveTab] = useState('all');
    const [showFilters, setShowFilters] = useState(false);
    const [showAddModal, setShowAddModal] = useState(false);

    const tabs = [
        { id: 'all', label: 'Все объявления' },
        { id: 'my', label: 'Мои объявления' },
        { id: 'participating', label: 'Участвую' }
    ];

    return (
        <div className={styles.homePage}>
            <div className={styles.hero}>
                <div className={styles.heroContent}>
                    <h1 className={styles.heroTitle}>
                        Найди свою команду для волейбола
                    </h1>
                    <p className={styles.heroSubtitle}>
                        Присоединяйся к играм, создавай объявления и находи единомышленников
                    </p>
                    <Button size="large" icon={FaPlus} onClick={() => setShowAddModal(true)}>
                        Создать объявление
                    </Button>
                </div>
            </div>

            <div className={styles.tabsSection}>
                <div className={styles.container}>
                    <div className={styles.tabsHeader}>
                        <div className={styles.tabs}>
                            {tabs.map(tab => (
                                <button
                                    key={tab.id}
                                    className={`${styles.tab} ${activeTab === tab.id ? styles.activeTab : ''}`}
                                    onClick={() => setActiveTab(tab.id)}
                                >
                                    {tab.label}
                                </button>
                            ))}
                        </div>
                        <Button
                            variant="outline"
                            size="small"
                            icon={FaFilter}
                            onClick={() => setShowFilters(!showFilters)}
                        >
                            Фильтры
                        </Button>
                    </div>

                    {showFilters && <FilterSection />}

                    <div className={styles.advertsGrid}>
                        <AdvertCard />
                        <AdvertCard isCreator={true} />
                        <AdvertCard isParticipating={true} />
                        <AdvertCard />
                        <AdvertCard isCreator={true} />
                        <AdvertCard />
                    </div>
                </div>
            </div>

            <Modal isOpen={showAddModal} onClose={() => setShowAddModal(false)} title="Создать объявление" size="large">
                <div>Форма создания объявления будет здесь</div>
            </Modal>
        </div>
    );
};

export default HomePage;
